  }

  .record-list__item {
    grid-template-columns: 1fr;
    gap: 0.5rem;
    padding-block: 1.25rem;
  }

  .record-list__summary {
    grid-column: auto;
  }

  .statistics-section-heading,
  .statistic-card__heading,
  .participant-statistics {
    grid-template-columns: 1fr;
    flex-direction: column;
  }

  .statistic-card,
  .event-trace,
  .statistics-warnings {
