@media (prefers-reduced-motion: reduce) {
  *,
  *::before,
  *::after {
    scroll-behavior: auto !important;
    transition-duration: 0.01ms !important;
    animation-duration: 0.01ms !important;
    animation-iteration-count: 1 !important;
  }
}

item.aggregated_output:
:root,
:root[data-theme='day'] {
  --colour-canvas: #f5f2e9;
  --colour-surface: #fffdf7;
  --colour-surface-raised: #eee9dc;
  --colour-text: #102026;
  --colour-text-secondary: #52636a;
  --colour-text-muted: #627078;
  --colour-border: #d9d3c4;
  --colour-primary: #5d7e00;
  --colour-primary-soft: #dff0a7;
  --colour-brand: #e95a24;
  --colour-data-accent: #007f9e;
  --colour-link: #005f77;
  --colour-label: #486200;
  --colour-brand-text: #a83b13;
  --colour-error: #b42318;
  --colour-focus: #007f9e;
  --colour-error: #d64251;
  --colour-error-soft: #fce8e8;
  --shadow-header: 0 8px 28px rgb(16 32 38 / 8%);
  --font-display: 'Arial Narrow', 'Roboto Condensed', Arial, sans-serif;
  --font-interface: 'Segoe UI', Arial, sans-serif;
  color: var(--colour-text);
  background: var(--colour-canvas);
  font-family: var(--font-interface);
  font-synthesis: none;
  text-rendering: optimizeLegibility;
}

:root[data-theme='night'] {
  --colour-canvas: #08121b;
  --colour-surface: #101e2b;
  --colour-surface-raised: #162736;
  --colour-text: #f6f8f2;
  --colour-text-secondary: #b8c3cc;
  --colour-text-muted: #8ea0af;
  --colour-border: #263847;
  --colour-primary: #c7ff4a;
  --colour-primary-soft: #263b21;
  --colour-brand: #ff6b35;
  --colour-data-accent: #20d5ff;
  --colour-link: #20d5ff;
  --colour-label: #c7ff4a;
  --colour-brand-text: #ff8a5e;
  --colour-error: #ff8a7a;
  --colour-focus: #c7ff4a;
  --colour-error: #ff5a67;
  --colour-error-soft: #361b24;
  --shadow-header: 0 8px 28px rgb(0 0 0 / 24%);
}

* {
  box-sizing: border-box;
}

html {
  min-width: 320px;
  background: var(--colour-canvas);
  scroll-behavior: smooth;
}

body {
  margin: 0;
  min-width: 320px;
  min-height: 100vh;
  overflow-x: hidden;
  background: var(--colour-canvas);
  color: var(--colour-text);
}

button,
input,
select {
  font: inherit;
}

a {
  color: var(--colour-link);
}

a:focus-visible,
button:focus-visible,
input:focus-visible,
select:focus-visible {
  outline: 3px solid var(--colour-focus);
  outline-offset: 4px;
}

.public-shell {
  min-height: 100vh;
  display: flex;
  flex-direction: column;
}

.skip-link {
  position: fixed;
  left: 1rem;
  top: -5rem;
  z-index: 100;
  padding: 0.75rem 1rem;
  border: 2px solid var(--colour-focus);
  border-radius: 6px;
  background: var(--colour-surface);
  color: var(--colour-text);
  font-weight: 600;
  text-decoration: none;
}

.skip-link:focus {
  top: 1rem;
}

.site-header {
  position: relative;
  z-index: 10;
  border-bottom: 1px solid var(--colour-border);
  background: var(--colour-surface);
  box-shadow: var(--shadow-header);
}

.site-header__inner,
.site-footer__inner,
.content-boundary {
  width: min(100% - 3rem, 100rem);
  margin-inline: auto;
}

.site-header__inner {
  min-height: 5.5rem;
  display: grid;
  grid-template-columns: auto minmax(0, 1fr) auto;
  align-items: center;
  gap: 1.5rem;
}

.site-header__controls,
.auth-navigation,
.auth-navigation-wrap {
  display: flex;
  align-items: center;
}

.site-header__controls {
  justify-content: flex-end;
  gap: 1.5rem;
}

.auth-navigation-wrap {
  position: relative;
  align-self: stretch;
}

.auth-navigation {
  gap: 0.5rem;
}

.auth-navigation a,
.auth-navigation button {
  min-height: 2.75rem;
  display: inline-flex;
  align-items: center;
  padding: 0.625rem 0.75rem;
  border: 1px solid transparent;
  border-radius: 6px;
  background: transparent;
  color: var(--colour-text);
  font-weight: 600;
  text-decoration: none;
  white-space: nowrap;
  cursor: pointer;
}

.auth-navigation a:hover,
.auth-navigation button:hover:not(:disabled),
.auth-navigation a[aria-current='page'] {
  border-color: var(--colour-border);
  background: var(--colour-surface-raised);
}

.auth-navigation a[aria-current='page'] {
  box-shadow: inset 0 -3px var(--colour-primary);
}

.auth-navigation button:disabled {
  cursor: wait;
  opacity: 0.7;
}

.auth-navigation__status {
  margin: 0;
  color: var(--colour-text-secondary);
  font-size: 0.875rem;
}

.auth-navigation__error {
  position: absolute;
  top: calc(100% - 0.25rem);
  right: 0;
  width: max-content;
  max-width: min(22rem, calc(100vw - 2rem));
  margin: 0;
  padding: 0.75rem 1rem;
  border: 1px solid var(--colour-error);
  border-radius: 6px;
  background: var(--colour-surface);
  color: var(--colour-error);
  box-shadow: var(--shadow-header);
  font-size: 0.875rem;
}

.brand-link {
  display: inline-flex;
  align-items: center;
  min-width: 0;
  border-radius: 6px;
}

.brand-wordmark {
  display: block;
  width: 11rem;
  max-width: 100%;
}

.brand-wordmark__image {
  display: block;
  width: 100%;
  height: auto;
}

.site-navigation {
  display: flex;
  align-items: center;
  justify-content: center;
  gap: 0.25rem;
}

.site-navigation a {
  position: relative;
  padding: 0.75rem 0.625rem;
  border-radius: 6px;
  color: var(--colour-text-secondary);
  font-size: 0.8125rem;
  font-weight: 650;
  text-align: center;
  text-decoration: none;
}

.site-navigation a:hover {
  background: var(--colour-surface-raised);
  color: var(--colour-text);
}

.site-navigation a.active {
  background: var(--colour-primary-soft);
  color: var(--colour-text);
}

.site-navigation a.active::after {
  content: '';
  position: absolute;
  right: 0.625rem;
  bottom: 0.375rem;
  left: 0.625rem;
  border-bottom: 2px solid var(--colour-primary);
}

.brand-asset--night {
  display: none;
}

:root[data-theme='night'] .brand-asset--day {
  display: none;
}

:root[data-theme='night'] .brand-asset--night {
  display: block;
}

.theme-control {
  display: flex;
  align-items: center;
  gap: 0.75rem;
  color: var(--colour-text-secondary);
}

.theme-control__label {
  font-size: 0.75rem;
  font-weight: 600;
  text-transform: uppercase;
}

.theme-toggle {
  position: relative;
  display: flex;
  align-items: center;
  gap: 0.625rem;
  cursor: pointer;
}

.theme-toggle input {
  position: absolute;
  width: 2.75rem;
  height: 1.5rem;
  margin: 0;
  opacity: 0;
  cursor: pointer;
}

.theme-toggle__track {
  width: 2.75rem;
  height: 1.5rem;
  flex: 0 0 auto;
  padding: 0.1875rem;
  border: 1px solid var(--colour-border);
  border-radius: 999px;
  background: var(--colour-surface-raised);
}

.theme-toggle__thumb {
  display: block;
  width: 1rem;
  height: 1rem;
  border-radius: 50%;
  background: var(--colour-primary);
  transform: translateX(0);
  transition: transform 160ms ease;
}

.theme-toggle input:checked + .theme-toggle__track .theme-toggle__thumb {
  transform: translateX(1.25rem);
}

.theme-toggle input:focus-visible + .theme-toggle__track {
  outline: 3px solid var(--colour-focus);
  outline-offset: 4px;
}

.theme-control__value {
  min-width: 5.75rem;
  color: var(--colour-text);
  font-size: 0.875rem;
  font-weight: 600;
}

main {
  flex: 1;
}

.auth-page {
  min-height: min(42rem, calc(100svh - 13.5rem));
  display: grid;
  place-items: center;
  padding-block: 4rem;
}

.auth-card {
  width: min(100%, 47.5rem);
  padding: 3rem;
  border: 1px solid var(--colour-border);
  border-radius: 10px;
  background: var(--colour-surface);
  box-shadow: var(--shadow-header);
}

.auth-card h1 {
  font-size: clamp(2.5rem, 8vw, 3.5rem);
  white-space: normal;
}

.auth-card__introduction,
.auth-card > p:not(.eyebrow, .auth-error) {
  max-width: 38rem;
  color: var(--colour-text-secondary);
  line-height: 1.6;
}

.auth-card__introduction {
  margin: 1.25rem 0 2rem;
  font-size: 1.0625rem;
}

.button {
  min-height: 3rem;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  padding: 0.75rem 1.25rem;
  border: 1px solid transparent;
  border-radius: 6px;
  font-weight: 600;
  cursor: pointer;
}

.button--primary {
  background: var(--colour-primary);
  color: #fff;
}

:root[data-theme='night'] .button--primary {
  color: #08121b;
}

.button:disabled {
  cursor: wait;
  opacity: 0.72;
}

.auth-error {
  margin: 1rem 0 0;
  color: var(--colour-error);
  font-weight: 600;
}

.auth-card__alternative {
  margin: 2rem 0 0;
}

.identity-details {
  margin: 2rem 0 0;
}

.identity-details div {
  padding-block: 1rem;
  border-block: 1px solid var(--colour-border);
}

.identity-details dt {
  color: var(--colour-text-secondary);
  font-size: 0.75rem;
  font-weight: 600;
  text-transform: uppercase;
}

.identity-details dd {
  margin: 0.5rem 0 0;
  font-weight: 600;
  overflow-wrap: anywhere;
}

.account-deletion {
  margin-top: 3rem;
  padding: 1.5rem;
  border: 1px solid var(--colour-error);
  border-radius: 6px;
  background: var(--colour-error-soft);
}

.account-deletion h2 {
  max-width: none;
  font-size: 1.75rem;
}

.account-deletion > p:not(.eyebrow, .auth-error) {
  max-width: 40rem;
  margin: 1rem 0 0;
  color: var(--colour-text-secondary);
  line-height: 1.6;
}

.account-deletion__form {
  display: grid;
  gap: 1.25rem;
  margin-top: 1.5rem;
}

.account-deletion__acknowledgement {
  display: flex;
  align-items: flex-start;
  gap: 0.75rem;
  line-height: 1.5;
}

.account-deletion__acknowledgement input {
  width: 1.25rem;
  height: 1.25rem;
  flex: 0 0 auto;
  margin-top: 0.125rem;
}

.account-deletion__confirmation {
  display: grid;
  gap: 0.5rem;
  font-weight: 600;
}

.account-deletion__confirmation input {
  width: min(100%, 20rem);
  min-height: 2.75rem;
  padding: 0.625rem 0.75rem;
  border: 1px solid var(--colour-border);
  border-radius: 6px;
  background: var(--colour-surface);
  color: var(--colour-text);
  font: inherit;
}

.account-deletion input:focus-visible,
.button--danger:focus-visible {
  outline: 3px solid var(--colour-focus);
  outline-offset: 3px;
}

.button--danger {
  justify-self: start;
  border-color: var(--colour-error);
  background: var(--colour-error);
  color: #fff;
}

