  border-block: 1px solid var(--colour-border);
}

.identity-details dt {
  color: var(--colour-text-secondary);
  font-size: 0.75rem;
  font-weight: 600;
  text-transform: uppercase;
}

.identity-details dd {
  margin: 0.5rem 0 0;
  font-weight: 600;
  overflow-wrap: anywhere;
}

.account-deletion {
  margin-top: 3rem;
  padding: 1.5rem;
  border: 1px solid var(--colour-error);
  border-radius: 6px;
  background: var(--colour-error-soft);
}

.account-deletion h2 {
