  gap: 1.25rem;
  margin-top: 1.5rem;
}

.account-deletion__acknowledgement {
  display: flex;
  align-items: flex-start;
  gap: 0.75rem;
  line-height: 1.5;
}

.account-deletion__acknowledgement input {
