  line-height: 1.6;
}

.submitter-access-panel__message > p,
.submitter-access-panel__error p {
  margin: 0;
}

.submitter-access-panel__message .button,
.submitter-access-panel__error .button {
  margin-top: 1rem;
}

.submitter-access-panel__actions {
