}

.submission-page {
  min-height: 38rem;
  padding-bottom: 5rem;
}

.admin-users-page {
  min-height: 38rem;
  padding-bottom: 5rem;
}

.admin-users-page__heading {
  border-bottom: 2px solid var(--colour-primary);
}

.admin-user-toolbar {
  display: flex;
  align-items: end;
  justify-content: space-between;
  gap: 1.5rem;
  padding-block: 2rem 1.25rem;
}

.admin-user-toolbar > div {
  display: grid;
  gap: 0.5rem;
  width: min(100%, 32rem);
}

.admin-user-toolbar label,
.admin-access-form legend {
  font-weight: 700;
}

.admin-user-toolbar input {
  width: 100%;
  min-height: 3rem;
  padding: 0.625rem 0.75rem;
  border: 1px solid var(--colour-border);
  border-radius: 6px;
  background: var(--colour-surface);
  color: var(--colour-text);
}

.admin-user-toolbar p {
  margin: 0 0 0.75rem;
  color: var(--colour-text-secondary);
  white-space: nowrap;
}

.admin-user-list {
  display: grid;
  grid-template-columns: repeat(2, minmax(0, 1fr));
  gap: 1.25rem;
}

.admin-user-card {
  min-width: 0;
  padding: 1.5rem;
  border: 1px solid var(--colour-border);
  border-radius: 10px;
  background: var(--colour-surface);
  box-shadow: var(--shadow-header);
}

.admin-user-card__header {
  display: flex;
  align-items: flex-start;
  justify-content: space-between;
  gap: 1rem;
}

.admin-user-card__header h2 {
  margin: 0.25rem 0 0;
  font-size: 1.5rem;
  overflow-wrap: anywhere;
}

.admin-user-card__id {
  margin: 0;
  color: var(--colour-text-muted);
  font-size: 0.75rem;
  font-weight: 700;
  letter-spacing: 0.06em;
  text-transform: uppercase;
}

.admin-role-badge {
  flex: 0 0 auto;
  padding: 0.375rem 0.625rem;
  border: 1px solid var(--colour-border);
  border-radius: 999px;
  background: var(--colour-surface-raised);
  color: var(--colour-text-secondary);
  font-size: 0.75rem;
  font-weight: 700;
  text-transform: uppercase;
}

.admin-role-badge--submitter {
  border-color: var(--colour-data-accent);
  color: var(--colour-text);
}

.admin-role-badge--admin {
  border-color: var(--colour-brand);
  color: var(--colour-brand-text);
}

.admin-user-facts {
  display: grid;
  grid-template-columns: repeat(2, minmax(0, 1fr));
  gap: 1rem;
  margin: 1.5rem 0;
}

.admin-user-facts div {
  min-width: 0;
}

.admin-user-facts__audit {
  grid-column: 1 / -1;
}

.admin-user-facts dt {
  color: var(--colour-text-muted);
  font-size: 0.75rem;
  font-weight: 700;
  text-transform: uppercase;
}

.admin-user-facts dd {
  margin: 0.35rem 0 0;
  line-height: 1.45;
  overflow-wrap: anywhere;
}

.admin-access-form {
  padding-top: 1.25rem;
  border-top: 1px solid var(--colour-border);
}

.admin-access-form fieldset {
  min-width: 0;
  margin: 0;
  padding: 0;
  border: 0;
}

.admin-access-form .field-help {
  margin-block: 0.5rem 0.75rem;
}

.admin-scope-options {
  display: grid;
  grid-template-columns: repeat(2, minmax(0, 1fr));
  gap: 0.5rem;
  max-height: 12rem;
  padding: 0.25rem;
  overflow-y: auto;
}

.admin-scope-options label {
  display: flex;
  align-items: flex-start;
  gap: 0.625rem;
  min-width: 0;
  padding: 0.625rem;
  border: 1px solid var(--colour-border);
  border-radius: 6px;
  background: var(--colour-surface-raised);
  cursor: pointer;
}

.admin-scope-options input {
  flex: 0 0 auto;
  width: 1.125rem;
  height: 1.125rem;
  margin: 0.1rem 0 0;
}

.admin-scope-options span {
  min-width: 0;
  overflow-wrap: anywhere;
}

.admin-access-form__actions {
  display: flex;
  flex-wrap: wrap;
  gap: 0.75rem;
  margin-top: 1rem;
}

.button--danger {
  border-color: var(--colour-error);
  background: transparent;
  color: var(--colour-error);
}

.admin-access-form__error,
.admin-access-form__empty,
.admin-user-card__protected,
.admin-access-feedback {
  margin: 1rem 0 0;
  line-height: 1.55;
}

.admin-access-form__error,
.admin-access-feedback--error {
  color: var(--colour-error);
  font-weight: 600;
}

.admin-user-card__protected {
  padding: 1rem;
  border-left: 3px solid var(--colour-border);
  background: var(--colour-surface-raised);
  color: var(--colour-text-secondary);
}

.admin-access-feedback {
  padding: 0.875rem 1rem;
  border-left: 3px solid var(--colour-data-accent);
  background: var(--colour-surface-raised);
}

.admin-access-feedback--error {
  border-left-color: var(--colour-error);
  background: var(--colour-error-soft);
}

.submission-page__heading {
  border-bottom: 2px solid var(--colour-primary);
}

.submission-form {
  display: grid;
  gap: 2rem;
  max-width: 62rem;
  padding-top: 2rem;
}

.submission-field {
  display: grid;
  gap: 0.625rem;
}

.submission-field label {
  font-family: var(--font-display);
  font-size: 1.25rem;
  font-weight: 700;
}

.submission-field select,
.submission-field textarea {
  width: 100%;
  min-width: 0;
  border: 1px solid var(--colour-border);
  border-radius: 6px;
  background: var(--colour-surface);
  color: var(--colour-text);
}

.submission-field select {
  min-height: 3rem;
  padding: 0.625rem 0.75rem;
}

.submission-field textarea {
  min-height: 24rem;
  padding: 1rem;
  resize: vertical;
  font-family: Consolas, 'Courier New', monospace;
  font-size: 0.875rem;
  line-height: 1.55;
  tab-size: 2;
  white-space: pre;
  overflow: auto;
}

.submission-field textarea[aria-invalid='true'] {
  border-color: var(--colour-error);
  box-shadow: 0 0 0 1px var(--colour-error);
}

.field-help,
.submission-progress {
  margin: 0;
  color: var(--colour-text-secondary);
  line-height: 1.5;
}

.field-help code {
  padding: 0.1rem 0.3rem;
  border-radius: 3px;
  background: var(--colour-surface-raised);
  color: var(--colour-text);
}

.submission-form > .button {
  justify-self: start;
}

.submission-result {
  padding: 1.5rem;
  border-left: 4px solid var(--colour-primary);
  background: var(--colour-primary-soft);
}

.submission-result--error {
  border-left-color: var(--colour-error);
  background: var(--colour-error-soft);
}

.submission-result h2 {
  max-width: none;
  font-size: 1.5rem;
}

.submission-result h2:focus {
  outline: 3px solid var(--colour-focus);
  outline-offset: 4px;
}

.submission-result > p {
  margin: 0.75rem 0 0;
  color: var(--colour-text-secondary);
  line-height: 1.55;
}

.submission-reference {
  display: grid;
  grid-template-columns: repeat(3, minmax(0, 1fr));
  gap: 1rem;
  margin: 1.5rem 0 0;
}

.submission-reference div {
  min-width: 0;
}

.submission-reference dt {
  color: var(--colour-text-secondary);
  font-size: 0.75rem;
  font-weight: 700;
  text-transform: uppercase;
}

.submission-reference dd {
  margin: 0.375rem 0 0;
  font-weight: 700;
  overflow-wrap: anywhere;
}

.validation-results {
  display: grid;
  gap: 0.75rem;
  margin: 1.5rem 0 0;
  padding-left: 1.5rem;
}

.validation-results li {
  padding-left: 0.25rem;
}

.validation-results strong,
.validation-results span {
  display: block;
}

.validation-results span {
  margin-top: 0.25rem;
  color: var(--colour-text-secondary);
  line-height: 1.5;
}

.hero {
  position: relative;
  min-height: min(39rem, calc(100svh - 7.5rem));
  overflow: hidden;
  display: flex;
  align-items: center;
  border-bottom: 1px solid var(--colour-border);
  background: var(--colour-canvas);
}

.hero::before,
.hero::after {
  content: '';
  position: absolute;
  pointer-events: none;
}

.hero::before {
  inset: 2rem 0 2rem 50%;
  border-left: 1px solid var(--colour-border);
}

.hero::after {
  right: 3rem;
  bottom: 2rem;
  width: 7rem;
  border-bottom: 0.5rem solid var(--colour-brand);
}

.hero__content {
  position: relative;
  z-index: 2;
  width: min(100% - 3rem, 100rem);
  margin-inline: auto;
  padding-block: 4rem;
}

.eyebrow {
  margin: 0 0 1rem;
  color: var(--colour-label);
  font-size: 0.75rem;
  font-weight: 600;
  text-transform: uppercase;
}

h1,
h2,
h3,
p {
  overflow-wrap: anywhere;
}

h1,
h2,
h3 {
  font-family: var(--font-display);
  letter-spacing: 0;
}

h1 {
  margin: 0;
  font-size: 4.5rem;
  line-height: 1;
  text-wrap: balance;
  white-space: nowrap;
}

.hero__tagline {
  max-width: 30rem;
  margin: 1.5rem 0 0;
  color: var(--colour-brand);
  font-family: var(--font-display);
  font-size: 2rem;
  font-weight: 700;
  line-height: 1.15;
}

.hero__summary {
  max-width: 35rem;
  margin: 1.5rem 0 0;
  color: var(--colour-text-secondary);
  font-size: 1.125rem;
  line-height: 1.6;
}

.hero__brand-art {
  position: absolute;
  z-index: 1;
  right: max(1.5rem, calc((100vw - 100rem) / 2));
  bottom: -1rem;
  width: min(38vw, 31rem);
  pointer-events: none;
}

.hero__logo {
  width: 100%;
  height: auto;
}

.principles {
  padding-block: 5rem;
  background: var(--colour-surface);
}

.section-heading {
  display: grid;
  grid-template-columns: minmax(8rem, 0.7fr) minmax(0, 2fr);
  align-items: end;
  gap: 2rem;
  padding-bottom: 2rem;
  border-bottom: 1px solid var(--colour-border);
}

.section-heading .eyebrow {
  margin: 0;
}

h2 {
  max-width: 18ch;
  margin: 0;
  font-size: 2.5rem;
  line-height: 1.1;
}

.principles__grid {
  display: grid;
  grid-template-columns: repeat(3, minmax(0, 1fr));
  gap: 2.5rem;
}

.principles article {
  padding-top: 2rem;
}

.principle-number {
  margin: 0 0 2rem;
  color: var(--colour-brand-text);
  font-family: var(--font-display);
  font-size: 0.875rem;
  font-weight: 700;
}

h3 {
  margin: 0;
  font-size: 1.5rem;
  line-height: 1.2;
}

.principles article p:last-child {
  max-width: 28ch;
  margin: 0.75rem 0 0;
  color: var(--colour-text-secondary);
  line-height: 1.6;
}

.site-footer {
  border-top: 1px solid var(--colour-border);
  background: var(--colour-surface-raised);
}

.site-footer__inner {
  min-height: 8rem;
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 2rem;
}

.site-footer p {
  margin: 0;
  color: var(--colour-text-secondary);
  font-size: 0.875rem;
}

.browse-page {
  min-height: 38rem;
  padding-bottom: 5rem;
}

.page-heading {
  padding-block: 3.5rem 2.5rem;
}

.page-heading h1 {
  max-width: 20ch;
  margin: 0;
  font-size: 3.25rem;
  line-height: 1;
  white-space: normal;
}

.page-heading > p:last-child {
  max-width: 47rem;
  margin: 1rem 0 0;
  color: var(--colour-text-secondary);
  font-size: 1.0625rem;
  line-height: 1.6;
}

.browse-page__content {
  display: grid;
  gap: 3rem;
}

.filter-panel {
  padding: 1.5rem;
  border: 1px solid var(--colour-border);
  border-radius: 6px;
  background: var(--colour-surface-raised);
}

.filter-panel__heading,
.results-heading {
  display: flex;
  align-items: baseline;
  justify-content: space-between;
  gap: 1rem;
}

.filter-panel h2,
.results-heading h2,
.related-records h2 {
  max-width: none;
  font-size: 1.5rem;
}

.text-link,
.back-link {
  color: var(--colour-link);
  font-weight: 650;
  text-underline-offset: 0.2em;
}

.filter-grid {
  display: grid;
  grid-template-columns: repeat(4, minmax(0, 1fr));
  gap: 1rem;
  margin-block: 1.25rem;
}

.field {
  display: grid;
  align-content: start;
  gap: 0.5rem;
  min-width: 0;
}

.field span {
  color: var(--colour-text-secondary);
  font-size: 0.8125rem;
  font-weight: 650;
}

.field input,
.field select {
  width: 100%;
  min-width: 0;
  min-height: 2.75rem;
  padding: 0.625rem 0.75rem;
  border: 1px solid var(--colour-border);
  border-radius: 6px;
  background: var(--colour-surface);
  color: var(--colour-text);
}

.button {
  display: inline-flex;
  min-height: 2.75rem;
  align-items: center;
  justify-content: center;
  padding: 0.625rem 1rem;
  border: 1px solid transparent;
  border-radius: 6px;
  cursor: pointer;
  font-weight: 700;
  text-decoration: none;
}

.button--primary {
  background: var(--colour-primary);
  color: var(--colour-surface);
}

:root[data-theme='night'] .button--primary {
  color: var(--colour-canvas);
}

.button--secondary {
  border-color: var(--colour-border);
  background: var(--colour-surface);
  color: var(--colour-text);
}

.button:hover {
  filter: brightness(0.94);
}

.results-region {
  min-width: 0;
}

.results-heading {
  padding-bottom: 1rem;
  border-bottom: 2px solid var(--colour-primary);
}

.results-heading p {
  margin: 0;
  color: var(--colour-text-muted);
  font-size: 0.875rem;
}

.record-list {
  margin: 0;
  padding: 0;
  list-style: none;
}

.record-list__item {
  display: grid;
  grid-template-columns: minmax(8rem, 0.7fr) minmax(0, 1.8fr) minmax(12rem, 1fr);
  align-items: center;
  gap: 1.5rem;
  padding-block: 1.5rem;
  border-bottom: 1px solid var(--colour-border);
}

.record-list__meta,
.record-list__summary {
  margin: 0;
  color: var(--colour-text-secondary);
  font-size: 0.875rem;
  line-height: 1.5;
}

.record-list__item h3 {
  min-width: 0;
}

.record-list__item h3 a {
  color: var(--colour-text);
  text-decoration-color: var(--colour-primary);
  text-decoration-thickness: 2px;
  text-underline-offset: 0.2em;
}

.state-message {
  margin-top: 1.5rem;
  padding: 1.5rem;
  border-left: 3px solid var(--colour-data-accent);
  background: var(--colour-surface-raised);
}

.state-message--error {
  border-left-color: var(--colour-error);
  background: var(--colour-error-soft);
}

.state-message h1,
.state-message h3,
.state-message p {
  max-width: 48rem;
}

.state-message h1,
.state-message h3 {
  margin: 0;
  white-space: normal;
}

.state-message p {
  margin: 0.75rem 0 0;
  color: var(--colour-text-secondary);
  line-height: 1.6;
}

.state-message .button {
  margin-top: 1rem;
}

.pagination {
  display: flex;
  justify-content: flex-end;
  padding-top: 1.5rem;
}

.pagination__end {
  margin: 1.5rem 0 0;
  color: var(--colour-text-muted);
  font-size: 0.875rem;
  text-align: right;
}

.detail-page {
  min-height: 38rem;
  padding-block: 2.5rem 5rem;
}

.page-heading--detail {
  padding-block: 2.5rem 2rem;
  border-bottom: 2px solid var(--colour-primary);
}

.record-facts {
  display: grid;
  grid-template-columns: repeat(3, minmax(0, 1fr));
  gap: 0 2rem;
  margin: 0;
}

.record-facts > div {
  min-width: 0;
  padding-block: 1.5rem;
  border-bottom: 1px solid var(--colour-border);
}

.record-facts dt {
  color: var(--colour-text-muted);
  font-size: 0.75rem;
  font-weight: 700;
  text-transform: uppercase;
}

.record-facts dd {
  margin: 0.5rem 0 0;
  overflow-wrap: anywhere;
  font-family: var(--font-display);
  font-size: 1.375rem;
  font-weight: 700;
}

.related-records {
  margin-top: 3rem;
}

.related-records > div {
  display: flex;
  flex-wrap: wrap;
  gap: 0.75rem 1.5rem;
  margin-top: 1rem;
}

.related-records a {
  font-weight: 700;
  text-underline-offset: 0.2em;
}

.state-message--detail {
  margin-top: 2rem;
}

.statistics-summary,
.statistics-section {
  margin-top: 3rem;
}

.statistics-section-heading,
.statistic-card__heading {
  display: flex;
  align-items: flex-start;
  justify-content: space-between;
  gap: 1.5rem;
}

.statistics-section-heading {
  padding-bottom: 1rem;
  border-bottom: 2px solid var(--colour-primary);
}

.statistics-section-heading h2,
.statistics-warnings h2 {
  max-width: none;
  margin: 0;
  font-size: 1.5rem;
}

.statistics-section-heading > p,
.statistics-section-heading > div > p,
.statistics-card__heading p,
.statistic-card__source-count,
.statistics-note,
.statistics-section__empty {
  color: var(--colour-text-secondary);
}

.statistics-section-heading > p,
.statistics-section-heading > div > p,
.statistic-card__heading p,
.statistic-card__source-count,
.statistics-note,
.statistics-section__empty {
  margin: 0;
}

.statistics-status {
  padding: 0.35rem 0.6rem;
  border: 1px solid var(--colour-border);
  border-radius: 999px;
  background: var(--colour-surface-raised);
  color: var(--colour-text);
  font-size: 0.8125rem;
  font-weight: 750;
  white-space: nowrap;
}

.statistics-status--partial {
  border-color: var(--colour-brand);
}

.statistics-warnings {
  margin-top: 2rem;
  padding: 1.5rem;
  border-left: 3px solid var(--colour-brand);
  background: var(--colour-surface-raised);
}

.statistics-warnings ul {
  margin: 1rem 0 0;
  padding-left: 1.25rem;
}

.statistics-warnings li + li {
  margin-top: 0.5rem;
}

.statistics-list,
.event-trace-list {
  display: grid;
  gap: 1rem;
  margin: 1rem 0 0;
  padding: 0;
  list-style: none;
}

.statistic-card,
.event-trace {
  min-width: 0;
  padding: 1.5rem;
  border: 1px solid var(--colour-border);
  border-radius: 6px;
  background: var(--colour-surface);
}

.statistic-card__heading h3,
.event-trace h3 {
  margin: 0.25rem 0 0;
  font-size: 1.25rem;
}

.statistic-card__heading h3 a {
  color: var(--colour-text);
  text-decoration-color: var(--colour-primary);
  text-underline-offset: 0.2em;
}

.statistic-card__association {
  margin-top: 0.5rem !important;
  font-size: 0.875rem;
}

.statistic-metrics,
.event-trace dl {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(8rem, 1fr));
  gap: 1rem;
  margin: 1.25rem 0 0;
}

.statistic-metrics > div,
.event-trace dl > div {
  min-width: 0;
}

.statistic-metrics dt,
.event-trace dt {
  color: var(--colour-text-muted);
  font-size: 0.75rem;
  font-weight: 700;
  text-transform: uppercase;
}

.statistic-metrics dd,
.event-trace dd {
  margin: 0.35rem 0 0;
  overflow-wrap: anywhere;
  font-family: var(--font-display);
  font-size: 1.25rem;
  font-weight: 700;
}

.participant-statistics {
  display: grid;
  grid-template-columns: repeat(2, minmax(0, 1fr));
  gap: 1.5rem;
}

.participant-statistics h4 {
  margin: 1.25rem 0 0;
}

.statistic-card__source-count,
.statistics-note,
.statistics-section__empty {
  margin-top: 1.25rem;
  line-height: 1.6;
}

.statistics-note {
  padding: 1rem;
  border-left: 3px solid var(--colour-data-accent);
  background: var(--colour-surface-raised);
}

@media (max-width: 56.25rem) {
  .site-header__inner {
    grid-template-columns: auto minmax(0, 1fr) auto;
    gap: 0.75rem;
  }

  .site-navigation {
    grid-column: 1 / -1;
    grid-row: 2;
    display: grid;
    grid-template-columns: repeat(5, minmax(0, 1fr));
    width: 100%;
    padding-bottom: 0.75rem;
  }

  .filter-grid {
    grid-template-columns: repeat(2, minmax(0, 1fr));
  }

  .record-list__item {
    grid-template-columns: minmax(7rem, 0.7fr) minmax(0, 1.5fr);
  }

  .record-list__summary {
    grid-column: 1 / -1;
  }

  .record-facts {
    grid-template-columns: repeat(2, minmax(0, 1fr));
  }

  .admin-user-list {
    grid-template-columns: 1fr;
  }

  .site-header__inner {
    flex-wrap: wrap;
    padding-block: 0.75rem;
  }

  .site-header__controls {
    width: 100%;
    justify-content: space-between;
    order: 2;
  }

  .auth-navigation-wrap {
    min-height: 2.75rem;
  }

  .hero__brand-art {
    right: -8rem;
    width: 26rem;
    opacity: 0.38;
  }

  .hero::before {
    left: 72%;
  }
}

@media (max-width: 39.9375rem) {
  .site-header__inner,
  .site-footer__inner,
