item.stdout:
  margin: 0;
  font-size: 1.5rem;
  line-height: 1.2;
}

.principles article p:last-child {
  max-width: 28ch;
  margin: 0.75rem 0 0;
  color: var(--colour-text-secondary);
  line-height: 1.6;
}

.site-footer {
  border-top: 1px solid var(--colour-border);
  background: var(--colour-surface-raised);
}

.site-footer__inner {
  min-height: 8rem;
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 2rem;
}

.site-footer p {
  margin: 0;
  color: var(--colour-text-secondary);
  font-size: 0.875rem;
}

.browse-page {
  min-height: 38rem;
  padding-bottom: 5rem;
}

.page-heading {
  padding-block: 3.5rem 2.5rem;
}

.page-heading h1 {
  max-width: 20ch;
  margin: 0;
  font-size: 3.25rem;
  line-height: 1;
  white-space: normal;
}

.page-heading > p:last-child {
  max-width: 47rem;
  margin: 1rem 0 0;
  color: var(--colour-text-secondary);
  font-size: 1.0625rem;
  line-height: 1.6;
}

.browse-page__content {
  display: grid;
  gap: 3rem;
}

.filter-panel {
  padding: 1.5rem;
  border: 1px solid var(--colour-border);
  border-radius: 6px;
  background: var(--colour-surface-raised);
}

.filter-panel__heading,
.results-heading {
  display: flex;
  align-items: baseline;
  justify-content: space-between;
  gap: 1rem;
}

.filter-panel h2,
.results-heading h2,
.related-records h2 {
  max-width: none;
  font-size: 1.5rem;
}

.text-link,
.back-link {
  color: var(--colour-link);
  font-weight: 650;
  text-underline-offset: 0.2em;
}

.filter-grid {
  display: grid;
  grid-template-columns: repeat(4, minmax(0, 1fr));
  gap: 1rem;
  margin-block: 1.25rem;
}

.field {
  display: grid;
  align-content: start;
  gap: 0.5rem;
  min-width: 0;
}

.field span {
  color: var(--colour-text-secondary);
  font-size: 0.8125rem;
  font-weight: 650;
}

.field input,
.field select {
  width: 100%;
  min-width: 0;
  min-height: 2.75rem;
  padding: 0.625rem 0.75rem;
  border: 1px solid var(--colour-border);
  border-radius: 6px;
  background: var(--colour-surface);
  color: var(--colour-text);
}

.button {
  display: inline-flex;
  min-height: 2.75rem;
  align-items: center;
  justify-content: center;
  padding: 0.625rem 1rem;
  border: 1px solid transparent;
  border-radius: 6px;
  cursor: pointer;
  font-weight: 700;
  text-decoration: none;
}

.button--primary {
  background: var(--colour-primary);
  color: var(--colour-surface);
}

:root[data-theme='night'] .button--primary {
  color: var(--colour-canvas);
}

.button--secondary {
  border-color: var(--colour-border);
  background: var(--colour-surface);
  color: var(--colour-text);
}

.button:hover {
  filter: brightness(0.94);
}

.results-region {
  min-width: 0;
}

.results-heading {
  padding-bottom: 1rem;
  border-bottom: 2px solid var(--colour-primary);
}

.results-heading p {
  margin: 0;
  color: var(--colour-text-muted);
  font-size: 0.875rem;
}

.record-list {
  margin: 0;
  padding: 0;
  list-style: none;
}

.record-list__item {
  display: grid;
  grid-template-columns: minmax(8rem, 0.7fr) minmax(0, 1.8fr) minmax(12rem, 1fr);
  align-items: center;
  gap: 1.5rem;
  padding-block: 1.5rem;
  border-bottom: 1px solid var(--colour-border);
}

.record-list__meta,
.record-list__summary {
  margin: 0;
  color: var(--colour-text-secondary);
  font-size: 0.875rem;
  line-height: 1.5;
}

.record-list__item h3 {
  min-width: 0;
}

.record-list__item h3 a {
  color: var(--colour-text);
  text-decoration-color: var(--colour-primary);
  text-decoration-thickness: 2px;
  text-underline-offset: 0.2em;
}

.state-message {
  margin-top: 1.5rem;
  padding: 1.5rem;
  border-left: 3px solid var(--colour-data-accent);
  background: var(--colour-surface-raised);
}

.state-message--error {
  border-left-color: var(--colour-error);
  background: var(--colour-error-soft);
}

.state-message h1,
.state-message h3,
.state-message p {
  max-width: 48rem;
}

.state-message h1,
.state-message h3 {
  margin: 0;
  white-space: normal;
}

.state-message p {
  margin: 0.75rem 0 0;
  color: var(--colour-text-secondary);
  line-height: 1.6;
}

.state-message .button {
  margin-top: 1rem;
}

.pagination {
  display: flex;
  justify-content: flex-end;
  padding-top: 1.5rem;
}

.pagination__end {
  margin: 1.5rem 0 0;
  color: var(--colour-text-muted);
  font-size: 0.875rem;
  text-align: right;
}

.detail-page {
  min-height: 38rem;
  padding-block: 2.5rem 5rem;
}

.page-heading--detail {
  padding-block: 2.5rem 2rem;
  border-bottom: 2px solid var(--colour-primary);
}

.record-facts {
  display: grid;
  grid-template-columns: repeat(3, minmax(0, 1fr));
  gap: 0 2rem;
  margin: 0;
}

.record-facts > div {
  min-width: 0;
  padding-block: 1.5rem;
  border-bottom: 1px solid var(--colour-border);
}

.record-facts dt {
  color: var(--colour-text-muted);
  font-size: 0.75rem;
  font-weight: 700;
  text-transform: uppercase;
}

.record-facts dd {
  margin: 0.5rem 0 0;
  overflow-wrap: anywhere;
  font-family: var(--font-display);
  font-size: 1.375rem;
  font-weight: 700;
}

.related-records {
  margin-top: 3rem;
}

.related-records > div {
  display: flex;
  flex-wrap: wrap;
  gap: 0.75rem 1.5rem;
  margin-top: 1rem;
}

.related-records a {
  font-weight: 700;
  text-underline-offset: 0.2em;
}

.state-message--detail {
  margin-top: 2rem;
}

.statistics-summary,
.statistics-section {
  margin-top: 3rem;
}

.statistics-section-heading,
.statistic-card__heading {
  display: flex;
  align-items: flex-start;
  justify-content: space-between;
  gap: 1.5rem;
}

.statistics-section-heading {
  padding-bottom: 1rem;
  border-bottom: 2px solid var(--colour-primary);
}

.statistics-section-heading h2,
.statistics-warnings h2 {
  max-width: none;
  margin: 0;
  font-size: 1.5rem;
}

.statistics-section-heading > p,
.statistics-section-heading > div > p,
.statistics-card__heading p,
.statistic-card__source-count,
.statistics-note,
.statistics-section__empty {
  color: var(--colour-text-secondary);
}

.statistics-section-heading > p,
.statistics-section-heading > div > p,
.statistic-card__heading p,
.statistic-card__source-count,
.statistics-note,
.statistics-section__empty {
  margin: 0;
}

.statistics-status {
  padding: 0.35rem 0.6rem;
  border: 1px solid var(--colour-border);
  border-radius: 999px;
  background: var(--colour-surface-raised);
  color: var(--colour-text);
  font-size: 0.8125rem;
  font-weight: 750;
  white-space: nowrap;
}

.statistics-status--partial {
  border-color: var(--colour-brand);
}

.statistics-warnings {
  margin-top: 2rem;
  padding: 1.5rem;
  border-left: 3px solid var(--colour-brand);
  background: var(--colour-surface-raised);
}

.statistics-warnings ul {
  margin: 1rem 0 0;
  padding-left: 1.25rem;
}

.statistics-warnings li + li {
  margin-top: 0.5rem;
}

.statistics-list,
.event-trace-list {
  display: grid;
  gap: 1rem;
  margin: 1rem 0 0;
  padding: 0;
  list-style: none;
}

.statistic-card,
.event-trace {
  min-width: 0;
  padding: 1.5rem;
  border: 1px solid var(--colour-border);
  border-radius: 6px;
  background: var(--colour-surface);
}

.statistic-card__heading h3,
.event-trace h3 {
  margin: 0.25rem 0 0;
  font-size: 1.25rem;
}

.statistic-card__heading h3 a {
  color: var(--colour-text);
  text-decoration-color: var(--colour-primary);
  text-underline-offset: 0.2em;
}

.statistic-card__association {
  margin-top: 0.5rem !important;
  font-size: 0.875rem;
}

.statistic-metrics,
.event-trace dl {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(8rem, 1fr));
  gap: 1rem;
  margin: 1.25rem 0 0;
}

.statistic-metrics > div,
.event-trace dl > div {
  min-width: 0;
}

.statistic-metrics dt,
.event-trace dt {
  color: var(--colour-text-muted);
  font-size: 0.75rem;
  font-weight: 700;
  text-transform: uppercase;
}

.statistic-metrics dd,
.event-trace dd {
  margin: 0.35rem 0 0;
  overflow-wrap: anywhere;
  font-family: var(--font-display);
  font-size: 1.25rem;
  font-weight: 700;
}

.participant-statistics {
  display: grid;
  grid-template-columns: repeat(2, minmax(0, 1fr));
  gap: 1.5rem;
}

.participant-statistics h4 {
  margin: 1.25rem 0 0;
}

.statistic-card__source-count,
.statistics-note,
.statistics-section__empty {
  margin-top: 1.25rem;
  line-height: 1.6;
}

.statistics-note {
  padding: 1rem;
  border-left: 3px solid var(--colour-data-accent);
  background: var(--colour-surface-raised);
}

@media (max-width: 56.25rem) {
  .site-header__inner {
    grid-template-columns: auto minmax(0, 1fr) auto;
    gap: 0.75rem;
  }

  .site-navigation {
    grid-column: 1 / -1;
    grid-row: 2;
    display: grid;
    grid-template-columns: repeat(5, minmax(0, 1fr));
    width: 100%;
    padding-bottom: 0.75rem;
  }

  .filter-grid {
    grid-template-columns: repeat(2, minmax(0, 1fr));
  }

  .record-list__item {
    grid-row: 1 / span 2;
    margin: 0;
  }

  .principles article p:last-child {
    max-width: none;
  }

  .site-footer__inner {
    min-height: 9rem;
    align-items: flex-start;
    flex-direction: column;
    justify-content: center;
    gap: 1rem;
  }

  .browse-page {
    padding-bottom: 3.5rem;
  }

  .page-heading {
    padding-block: 2.5rem 2rem;
  }

  .page-heading h1 {
    font-size: 2.5rem;
  }

  .filter-panel {
    margin-inline: -0.75rem;
    padding: 1.25rem 0.75rem;
    border-right: 0;
    border-left: 0;
    border-radius: 0;
  }

  .filter-panel__heading,
  .results-heading {
    align-items: flex-start;
    flex-direction: column;
  }

  .filter-grid,
  .record-facts {
    grid-template-columns: 1fr;
  }

  .record-list__item {
    grid-template-columns: 1fr;
    gap: 0.5rem;
    padding-block: 1.25rem;
  }

  .record-list__summary {
    grid-column: auto;
  }

  .statistics-section-heading,
  .statistic-card__heading,
  .participant-statistics {
    grid-template-columns: 1fr;
    flex-direction: column;
  }

  .statistic-card,
  .event-trace,
  .statistics-warnings {
    padding: 1.25rem;
  }

  .statistic-metrics,
  .event-trace dl {
    grid-template-columns: repeat(2, minmax(0, 1fr));
  }

  .pagination,
  .pagination .button {
    width: 100%;
  }

  .pagination__end {
    text-align: left;
  }

  .detail-page {
    padding-block: 2rem 3.5rem;
  }

  .submission-page {
    padding-bottom: 3.5rem;
  }

  .admin-users-page {
    padding-bottom: 3.5rem;
  }

  .submission-form {
    gap: 1.5rem;
  }

  .submission-field textarea {
    min-height: 20rem;
    padding: 0.75rem;
    font-size: 0.8125rem;
  }

  .submission-form > .button {
    width: 100%;
  }

  .submission-reference {
    grid-template-columns: 1fr;
  }
}

import type { CollectionResponse } from '../../api/public-read';
import { type FormEvent, type ReactNode, useCallback } from 'react';
import { Link, useSearchParams } from 'react-router-dom';
import { usePublicData } from './usePublicData';

export interface FilterField {
  label: string;
  name: string;
  placeholder?: string;
  type?: 'date' | 'search' | 'text';
}

interface BrowseCollectionProps<Resource> {
  description: string;
  emptyMessage: string;
  eyebrow: string;
  filters: FilterField[];
  load: (search: string, signal: AbortSignal) => Promise<CollectionResponse<Resource>>;
  renderItem: (resource: Resource) => ReactNode;
  resourceLabel: string;
  title: string;
}

const paginationKeys = ['cursor', 'limit'];

function normalizedSearch(searchParams: URLSearchParams, filters: FilterField[]): string {
  const allowedKeys = new Set([...paginationKeys, ...filters.map(({ name }) => name)]);
  const requestParams = new URLSearchParams();

  searchParams.forEach((value, key) => {
    if (allowedKeys.has(key) && value.trim()) {
      requestParams.set(key, value);
    }
  });

  const query = requestParams.toString();
  return query ? `?${query}` : '';
}

function FilterForm({ fields }: { fields: FilterField[] }) {
  const [searchParams, setSearchParams] = useSearchParams();

  function applyFilters(event: FormEvent<HTMLFormElement>) {
    event.preventDefault();
    const values = new FormData(event.currentTarget);
    const nextSearch = new URLSearchParams();

    values.forEach((value, key) => {
      const text = String(value).trim();
      if (text) {
        nextSearch.set(key, text);
      }
    });

    setSearchParams(nextSearch);
  }

  return (
    <form className="filter-panel" key={searchParams.toString()} onSubmit={applyFilters}>
      <div className="filter-panel__heading">
        <h2>Filter records</h2>
        <Link className="text-link" to=".">
          Clear filters
        </Link>
      </div>
      <div className="filter-grid">
        {fields.map(({ label, name, placeholder, type = 'text' }) => (
          <label className="field" key={name}>
            <span>{label}</span>
            <input
              defaultValue={searchParams.get(name) ?? ''}
              name={name}
              placeholder={placeholder}
              type={type}
            />
          </label>
        ))}
        <label className="field">
          <span>Records per page</span>
          <select defaultValue={searchParams.get('limit') ?? '50'} name="limit">
            <option value="25">25</option>
            <option value="50">50</option>
            <option value="100">100</option>
          </select>
        </label>
      </div>
      <button className="button button--primary" type="submit">
        Apply filters
      </button>
    </form>
  );
}

export function BrowseCollection<Resource>({
  description,
  emptyMessage,
  eyebrow,
  filters,
  load,
  renderItem,
  resourceLabel,
  title,
}: BrowseCollectionProps<Resource>) {
  const [searchParams] = useSearchParams();
  const search = normalizedSearch(searchParams, filters);
  const loadRecords = useCallback((signal: AbortSignal) => load(search, signal), [load, search]);
  const state = usePublicData(loadRecords, search);

  return (
    <div className="browse-page">
      <header className="page-heading content-boundary">
        <p className="eyebrow">{eyebrow}</p>
        <h1>{title}</h1>
        <p>{description}</p>
      </header>

      <div className="browse-page__content content-boundary">
        <FilterForm fields={filters} />

        <section aria-labelledby="results-heading" className="results-region">
          <div className="results-heading">
            <h2 id="results-heading">Published {resourceLabel}</h2>
            {state.status === 'ready' ? (
              <p aria-live="polite">
                {state.data.data.length} {state.data.data.length === 1 ? 'record' : 'records'} on
                this page
              </p>
            ) : null}
          </div>

          {state.status === 'loading' ? (
            <div className="state-message" role="status">
              <h3>Loading {resourceLabel}</h3>
              <p>Published records are being requested from the Sport Analytics API.</p>
            </div>
          ) : null}

          {state.status === 'error' ? (
            <div className="state-message state-message--error" role="alert">
              <h3>{title} could not be loaded</h3>
              <p>{state.error.message}</p>
              <button className="button button--secondary" onClick={state.reload} type="button">
                Try again
              </button>
            </div>
          ) : null}

          {state.status === 'ready' && state.data.data.length === 0 ? (
            <div className="state-message" role="status">
              <h3>No {resourceLabel} found</h3>
              <p>{emptyMessage}</p>
            </div>
          ) : null}

          {state.status === 'ready' && state.data.data.length > 0 ? (
            <>
              <ul className="record-list">{state.data.data.map(renderItem)}</ul>
              {state.data.pagination.nextCursor ? (
                <nav aria-label={`${title} pagination`} className="pagination">
                  <Link
                    className="button button--secondary"
                    to={{
                      search: (() => {
                        const nextSearch = new URLSearchParams(searchParams);
                        nextSearch.set('cursor', state.data.pagination.nextCursor);
                        return `?${nextSearch.toString()}`;
                      })(),
                    }}
                  >
                    Next page
                  </Link>
                </nav>
              ) : (
                <p className="pagination__end">End of published results</p>
              )}
            </>
          ) : null}
        </section>
      </div>
    </div>
  );
}
