test('anonymous users navigate the responsive fixture statistics and event trace', async ({
  page,
}) => {
  const requestedUrls: string[] = [];

  await page.route('**/api/v1/**', async (route) => {
    const url = new URL(route.request().url());
    requestedUrls.push(url.toString());

    if (url.pathname.endsWith('/statistics/stat-innings-1')) {
      await route.fulfill({
        json: {
          data: {
            ...inningsStatistic,
            contributingEvents: [
              {
                eventId: 'event-1',
                fixtureId: 'fixture-1',
                inningsId: 'innings-1',
                inningsOrdinal: 0,
                sequenceNumber: 1,
                strikerParticipantId: 'striker-1',
                bowlerParticipantId: 'bowler-1',
                runs: { offBat: 4, extras: 1, total: 5 },
                extras: {
                  wides: 1,
                  noBalls: null,
                  byes: null,
                  legByes: null,
                  penalty: null,
                },
                nonBoundary: false,
                bowlerWickets: 0,
              },
            ],
          },
        },
      });
      return;
    }

    if (url.pathname.endsWith('/statistics')) {
      await route.fulfill({
        json: {
          data: {
            fixtureId: 'fixture-1',
            status: 'complete',
            scope: { superOversIncluded: false },
            outcome: {
